const pages = $input.all().map(item => item.json);

const workflows = [];
for (const page of pages) {
  if (Array.isArray(page.data)) workflows.push(...page.data);
}

const now = new Date();

const dateFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

const timeFormatter = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Kolkata',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
});

const backupDate = dateFormatter.format(now);
const backupTime = timeFormatter.format(now);
const executionId = String($execution?.id || Date.now());

const backup = {
  backupVersion: 1,
  backupCreatedAt: now.toISOString(),
  backupCreatedAtIST: `${backupDate} ${backupTime} IST`,
  source: {
    n8nBaseUrl: 'https://n8n.flowexa.space',
    api: '/api/v1/workflows',
  },
  workflowCount: workflows.length,
  workflows,
  notes: [
    'Generated automatically from the n8n REST API.',
    'Credential secret values are not included by the workflow API response; credentials must be recreated/reconnected after a disaster restore.',
    'Keep the GitHub repository PRIVATE, especially if any workflow contains hard-coded secrets in node parameters.'
  ]
};

const json = JSON.stringify(backup, null, 2);
const githubOwner = 'saudagarzeeshan25-commits';
const githubRepo = 'N8N-hostinger-Back-Up';
const githubBranch = 'main';

return [{
  json: {
    backupDate,
    backupTime,
    executionId,
    workflowCount: workflows.length,
    githubOwner,
    githubRepo,
    githubBranch,
    githubPath: `n8n-backups/${backupDate}/backup-${executionId}.json`,
    commitMessage: `Daily n8n workflow backup — ${backupDate}`,
    backupContent: json
  }
}];

